/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        bonusTrail: null,       // super bonus 数据
    },

    init(deskInfo,gameId,gameJackpot) {
        this._super(deskInfo,gameId,gameJackpot);
        this.bonusTrail = this._deskInfo.bonusTrail;
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg(){
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            this.bonusTrail = msg.bonusTrail;
            msg.resultCards.push(20,20,20,20,20)
        }
        this._super(msg);
    },

    SetSubGameData:function(data){
        this._subGame = data;
    },

    GetSubGameData:function(){
        return this._subGame;
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this._gameInfo.freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
            return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    ///////////////////////////收集相关/////////////////

    /**
     * 获取结果中收集图标得的下标
     */
    getCollectSymbolIndexs() {
        let cards = this._gameInfo.resultCards
        if(!cards || cards.length < 1) {
            return [];
        }
        let ret = [];
        cards.forEach((v, i)=>{
            if(this.getGameCfg().isEnergyId(v)) {
                ret.push(i+1);
            }
        });
        return ret;
    },

    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg){
        console.log("<<<< reqSubGame-resp: ", msg);
        if(msg.data.rtype == 1){
            SlotsFacade.storeGame.onMsg(msg);
        } else if(msg.data.rtype == 3){
        }
    },

    /**
     * 获取图标奖励数据
     * @returns {null|{jackpotData: [], honeycombData: [], goldData: [], sum: *, rewardIdxs}}
     */
    getRewardData() {
        let rewardIdxs = this.getSpinData().rewardIdxs;
        if(!rewardIdxs || rewardIdxs.length<1) {
            return null;
        }
        // 整理数据
        let bonusIdxs = this.getSpinData().bonusIdxs;
        let bonusItems = this.getSpinData().bonusItems;
        let honeycombData = [];//蜂巢数据
        let jackpotData = [];// jackpot数据
        let goldData = [];  // 金币中奖数据
        for(let i=0; i<rewardIdxs.length; i++) {
            let idx = rewardIdxs[i];
            let index = bonusIdxs.indexOf(idx);
            if(index != -1) {
                let item = bonusItems[index];
                if(item.coin) {
                    goldData.push({idx:idx, item:item});
                }else if(item.jackpot) {
                    jackpotData.push({idx:idx, item:item});
                }else if(item.wheel) {
                    honeycombData.push({idx:idx, item:item});
                }
            }else {
                console.log("#err数据出错rewardIdxs", rewardIdxs, bonusIdxs, bonusItems);
            }
        }
        // 结算排序
        honeycombData.sort((a, b)=>{
            let idxInfoA = SlotsFacade.slots.transferIdx(a.idx);
            let idxInfoB = SlotsFacade.slots.transferIdx(b.idx);
            if(idxInfoA.col != idxInfoB.col) {
                return idxInfoA.col - idxInfoB.col;
            }
            return idxInfoA.row - idxInfoB.row;
        });
        jackpotData.sort((a, b)=>{
            let idxInfoA = SlotsFacade.slots.transferIdx(a.idx);
            let idxInfoB = SlotsFacade.slots.transferIdx(b.idx);
            if(idxInfoA.col != idxInfoB.col) {
                return idxInfoA.col - idxInfoB.col;
            }
            return idxInfoA.row - idxInfoB.row;
        });

        return {rewardIdxs, honeycombData, jackpotData, goldData};
    },

    /**
     * 获取卷轴列的 cards
     * @param reelIdx
     */
    getReelCards(reelIdx) {
        let ret = [];
        let cards = this.getSpinData().resultCards;
        for(let i=0; i<cards.length; i++) {
            if(i%5 == reelIdx) {
                ret.push(cards[i]);
            }
        }
        return ret;
    }
});
