
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        // 搜集信息相关
        collect_info_node: cc.Node,
        progress: cc.Node,
        items: [cc.Node],
        tips_btn: cc.Button,
        tips: cc.Node,

        // 免费信息相关
        free_info_node: cc.Node,
        free_normal_title: cc.Node,
        free_super_title: cc.Node,

        _step: 0,
        _topZIndex: 100,
    },

    onLoad() {
        this.tips.active = false;
        this.tips_btn.node.on("click", () => {
            this._showTips();
        }, this);
    },

    start() {
        this._step = SlotsFacade.dm.bonusTrail.count;
        this.setStep(this._step);
    },

    /**
     * 显示super free game 说明提示
     */
    _showTips() {
        if (this.tips.active) {
            return;
        }
        this.tips.active = true;
        this.tips.opacity = 0;
        cc.tween(this.tips)
            .to(0.5, { opacity: 0xff })
            .delay(2)
            .to(0.5, { opacity: 0 })
            .call(() => {
                this.tips.active = false;
            })
            .start();
    },

    /**
     * 添加步数
     */
    async addStep() {
        console.log(`添加步数，当前步数:${this._step}`);
        if (this._step == 4) {
            SlotsFacade.soundMgr.playEffect("sound_WildGorilla_super_collect");
        } else {
            SlotsFacade.soundMgr.playEffect("sound_WildGorilla_normal_collect");
        }
        this._topZIndex++;
        let item = this.items[this._step];
        item.zIndex = this._topZIndex;
        // icon 动画
        let icon = item.getChildByName("icon");
        icon.active = true;
        cc.tween(icon)
            .to(0.3, { scale: 1.5 })
            .to(0.2, { scale: 1 })
            .start();
        await SlotsFacade.delayTime(0.5);

        // icon背景动画
        // let ani = item.getChildByName("ani");
        // ani.active = true;
        // let aniCmp = ani.getComponent(cc.Animation);
        // aniCmp.play();
        // await new Promise(res=>{
        //     aniCmp.on("finished", ()=>{
        //         ani.active =false;
        //         aniCmp.off("finished");
        //         res();
        //     }, this);
        // })
        this._step += 1;
    },

    /**
     * 设置步数
     */
    setStep(step) {
        // console.log(`设置收集进度步数:${step}`);
        this._step = step;
        for (let i = 0; i < this.items.length; i++) {
            let item = this.items[i];
            // item.getChildByName("ani").active = false;
            // item.getChildByName("light").active = false;
            let icon = item.getChildByName("icon");
            icon.active = step > i ? true : false;
        }
    },

    /**
     * 设置super game 信息按钮状态
     */
    enableTipsBtn(boo) {
        this.tips_btn.interactable = boo;
    },

    hide() {
        this.collect_info_node.active = false;
        this.free_info_node.active = true;
        this.free_normal_title.active = SlotsFacade.dm.bonusTrail.count != SlotsFacade.dm.bonusTrail.totalCount;
        this.free_super_title.active = !this.free_normal_title.active;
    },

    show() {
        this.collect_info_node.active = true;
        this.free_info_node.active = false;
        this.setStep(SlotsFacade.dm.bonusTrail.count);
    }
});
