
/**
 * 浪漫女王slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        mask: cc.Node,
        rightReelNode: cc.Node,
    },

    onLoad() {
        this._super();
        this.rightReelNode = cc.find("reels/right", this.node);
    },

    /**
     * @override
     * @param col
     * @param row
     */
    createReels: function (col, row) {
        let reelCmp = this._cfg.scripts.Reels
        // left
        for (let i = 0; i < 2; i++) {
            let node = cc.find("reels/left/reel" + (i + 1), this.node)
            let scp = node.addComponent(reelCmp)
            scp.Init(i, row, this._topAniNode)
            this._reels.push(scp)
        }
        // right
        for (let i = 2; i < 5; i++) {
            let node = cc.find("reels/right/reels/reel" + (i + 1), this.node)
            let scp = node.addComponent(reelCmp)
            scp.Init(i, row, this._topAniNode)
            this._reels.push(scp)
        }
    },

    //重写
    StartMove: function () {
        this._super()
        SlotsFacade.flowCtrl.startMove();
        if (SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    //重写
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow: function () {
        this.scheduleOnce(() => {
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx - 1;
        let col = idx % this._col
        let row = this._row - Math.floor(idx / this._col) - 1;
        return { col: col, row: row };
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 设置symbol数据
     * @param cards
     * @constructor
     */
    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            // if(this._cfg.symbol[cards[i]]){
            let res = {}
            res.sid = cards[i] //符号id
            res.data = { idx: i + 1 };
            if (!reelResults[col]) reelResults[col] = []
            reelResults[col].unshift(res)
            // }
        }
        let spinData = SlotsFacade.dm.getSpinData();
        // 设置bonus数据
        if (spinData.bonusInfo) {
            let loseItems = spinData && spinData.bonusInfo && spinData.bonusInfo.loseItems
            if (!Array.isArray(loseItems)) {
                loseItems = []
            }
            let bonusItems = loseItems.concat(spinData.bonusInfo.winItems);
            if (!Array.isArray(bonusItems)) { bonusItems = [] }
            for (let item of bonusItems) {
                let idxInfo = this.transferIdx(item.idx);
                if (item.idx && idxInfo && idxInfo.col && idxInfo.row) {
                    let data = reelResults[idxInfo.col][idxInfo.row].data;
                    if (item.coin) {
                        data.coin = item.coin;
                    } else if (item.jackpot) {
                        data.jackpot = item.jackpot.id;
                    }
                    let sd = spinData && spinData.bonusInfo && spinData.bonusInfo.winItems
                    if (!Array.isArray(sd)) { sd = [] }
                    if (/*spinData.bonusInfo.winItems*/sd.includes(item)) {
                        data.isWinBonus = true;
                    }
                }
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_FreeSpin_trigger");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 展开卷轴
     * @returns {Promise<void>}
     */
    async expandReel() {
        let spinData = SlotsFacade.dm.getSpinData();
        let bonusInfo = spinData.bonusInfo;
        if (!bonusInfo || !bonusInfo.isTrigger) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_trigger_bonus");
        SlotsFacade.character.playAction();
        // 显示火特效
        let effect = this.rightReelNode.getChildByName("effect");
        effect.active = true;
        effect.opacity = 0;
        cc.tween(effect)
            .to(0.3, { opacity: 0xff })
            .start();
        await SlotsFacade.delayTime(0.3);

        // 扩展卷轴
        let expandCnt = 0;
        let maskHeight = 440;
        let resultCards = spinData.resultCards;
        let blankId = SlotsFacade.dm.getGameCfg().blankId;
        if (resultCards[4] != blankId) {
            expandCnt = 2;
            maskHeight = 635;
        } else if (resultCards[9] != blankId) {
            expandCnt = 1;
            maskHeight = 515;
        }
        if (expandCnt == 1) {
            SlotsFacade.soundMgr.playEffect("sound_WildGorilla_fire3to4");
        } else if (expandCnt == 2) {
            SlotsFacade.soundMgr.playEffect("sound_WildGorilla_fire3to5");
        }
        if (expandCnt > 0) {
            cc.tween(this.rightReelNode)
                .delay(0.2)
                .to(0.5, { height: maskHeight })
                .start();
        }
        this.rightReelNode.isExpand = true;
        await SlotsFacade.delayTime(2);
    },

    /**
     * 收起卷轴
     * @returns {Promise<void>}
     */
    async collapseReel() {
        if (!this.rightReelNode.isExpand) {
            return;
        }
        cc.tween(this.rightReelNode)
            .to(0.5, { height: 440 })
            .call(() => {
                this.rightReelNode.isExpand = false;
            })
            .start();
        // 隐藏火特效
        let effect = this.rightReelNode.getChildByName("effect");
        cc.tween(effect)
            .to(0.2, { opacity: 0 })
            .start();
        await SlotsFacade.delayTime(0.7);
    },

    update(dt) {
        if (this._stopTime > 0) {
            this._stopTime = this._stopTime - dt
            if (this._stopTime <= 0) { //空转时间到了
                if (this.CanStopSlot()) {//满足开始停止的条件
                    this._roundSpineTime = 0;
                    let expandReelTime = 0; // 扩展卷轴时间
                    let bonusInfo = SlotsFacade.dm.getSpinData().bonusInfo;
                    if (bonusInfo && bonusInfo.isTrigger) {
                        expandReelTime = 2;
                    } else {
                        this._bottomScript.ShowBtnsByState("moveing_2")
                    }
                    //倒计时完，设置一次
                    for (let i = 0; i < this._reels.length; i++) {
                        let item = this._reels[i]
                        let reelStopInterv = this.GetReelStopInter(i)
                        if (i > 1) {
                            reelStopInterv += (i - 1) * expandReelTime;
                        }
                        item.StopMove(reelStopInterv)
                    }
                }
                else {
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt

                    //记录一个超时时间.
                    this._roundSpineTime = this._roundSpineTime || 0
                    this._roundSpineTime += dt
                    if (this._roundSpineTime > 30) {
                        // this._stopTime = -1
                        this._topScript.SetBackLobby(true)
                    }
                }

            }
        }
    },

    /**
     * 单列停止
     * colIdx:0开始
     * 回弹动作执行之前的停止时机
     * @override
     * @param colIdx
     * @constructor
     */

    OnReelSpinEnd: function (colIdx) {
        if (colIdx == 1) {
            this.expandReel();
        }
    },
});
