/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node,
        bg_dark:cc.Node,
    },

    onLoad() {
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    showBgDark(boo) {
        this.bg_dark.active = boo;
    },

    /**
     * 显示赢取免费次数
     * @param {*} cnt
     * @param {*} isFirstTrigger 是否是首次触发
     */
    async showWinFreeCnt(cnt, isFirstTrigger) {
        if(isFirstTrigger) {
            Global.SlotsSoundMgr.stopBgm();
        }
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_tips_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 0;
        // 文本
        let label = panel.getChildByName("label");
        label.getComponent(cc.Label).string = cnt.toString();
        // 按钮
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.active = isFirstTrigger;
        // 提示
        panel.getChildByName("tips2").active = !isFirstTrigger;

        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale: 1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        })

        if(isFirstTrigger) {
            await new Promise(res => {
                let handler = () => {
                    SlotsFacade.soundMgr.playEffect("click");
                    okBtn.stopAllActions();
                    okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                    cc.tween(panel)
                        .to(0.5, {scale: 0}, {easing:"backIn"})
                        .call(()=>{
                            this.showBg(false);
                            panel.active = false;
                            res();
                        })
                        .start();
                };
                cc.vv.gameData.checkAutoPlay(okBtn, handler)
                okBtn.on(cc.Node.EventType.TOUCH_END, handler);
            });
        } else {
            await SlotsFacade.delayTime(1.5);
            SlotsFacade.soundMgr.playEffect("dialog_close");
            await new Promise(res=>{
                cc.tween(panel)
                    .to(0.5, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            });
        }
    },

    /**
     * 赢取super free game
     * @param cnt
     * @returns {Promise<void>}
     */
    async showWinSuperFreeCnt(cnt) {
        Global.SlotsSoundMgr.stopBgm();
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_tips_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_super_free_cnt");
        panel.active = true;
        panel.scale = 0;

        // 文本
        let label = panel.getChildByName("label");
        label.getComponent(cc.Label).string = cnt.toString();

        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale: 1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        })
        await new Promise(res => {
            let handler = () => {
                SlotsFacade.soundMgr.playEffect("dialog_close");
                okBtn.stopAllActions();
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.8, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler)
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取免费游戏金币
     * @param {number} goldNumb
     */
    async showWinFreeGold(goldNumb, cnt, isSuperFree) {
        Global.SlotsSoundMgr.stopBgm();
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_freespin_over");
        isSuperFree = isSuperFree || false;
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_coin");
        panel.active = true;
        panel.scale = 0;
        // 文本
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);
        panel.getChildByName("label_cnt").getComponent(cc.Label).string = cnt.toString();
        // 提示
        panel.getChildByName("tips_normal").active = !isSuperFree;
        panel.getChildByName("tips_super").active = isSuperFree;
        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale: 1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        })
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("dialog_close");
                okBtn.stopAllActions()
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);

                let delayT = 0;
                if(Global.FormatCommaNumToNum(label.getComponent(cc.Label).string) < goldNumb){
                    label.getComponent("LabelRollCmp").stopRoll();
                    label.getComponent(cc.Label).string = Global.FormatNumToComma(goldNumb);
                    delayT += 0.3;
                }

                cc.tween(panel)
                    .delay(delayT)
                    .to(0.8, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler)
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取jp奖励
     * @param {*} jpType  jackport类型 1~4 mini-grand
     * @param {*} goldNumb
     */
    async showWinJPGold(jpType, goldNumb) {
        SlotsFacade.soundMgr.playEffect("sound_WildGorilla_guochang_open");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        // 文本
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);
        // 提示
        let titleCmp = panel.getChildByName("title").getComponent("ImgSwitchCmp");
        titleCmp.setIndex(jpType-1);
        // 按钮
        let okBtn = panel.getChildByName("btn_ok");

        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale: 1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        })
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("dialog_close");
                okBtn.stopAllActions()
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);

                let delayT = 0;
                if(Global.FormatCommaNumToNum(label.getComponent(cc.Label).string) < goldNumb){
                    label.getComponent("LabelRollCmp").stopRoll();
                    label.getComponent(cc.Label).string = Global.FormatNumToComma(goldNumb);
                    delayT += 0.3;
                }

                cc.tween(panel)
                    .delay(delayT)
                    .to(0.8, {scale: 0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler)
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },
})