cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        label:cc.Label,
        jackpot:cc.Node,
        bonusKuang:cc.Node,
    },

    onLoad () {
        this.label = this.node.getChildByName("label").getComponent(cc.Label);
        this.jackpot = this.node.getChildByName("jackpot");
        this.bonusKuang = this.node.getChildByName("kuang_bonus");
    },

    //重写
    StartMove: function () {
        this._super();
        this.showLabel();
        this.showBonusKuang();
    },

    /**
     * @override
     * @param {*} id
     * @param {*} data
     */
    ShowById:function(id,data){
        let cfg = cc.vv.gameData.getGameCfg()
        if(id == cfg.blankId) {
            id = this.getRandomId();
            if(id == cc.vv.gameData.getGameCfg().bonusId) {
                data = {};
                data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
            }
        }
        this._super(id,data);
        if(data) {
            this.showLabel(true);
        }else {
            this.showLabel(false);
        }
    },

    /**
     * 随机 symbol id
     * @returns {*}
     */
    getRandomId() {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        let randVal = cfg.randomSymbols[randIdx-1];
        return randVal;
    },

    /**
     * 显示随机符号
     * @override
     */
    ShowRandomSymbol(){
        let randVal = this.getRandomId();
        let data = null;
        if(randVal == cc.vv.gameData.getGameCfg().bonusId) {
            data = {};
            data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
        }
        this.ShowById(randVal, data);
    },

    /**
     * 显示金币
     * @param boo
     */
    showLabel(boo) {
        if(boo && this._data && (this._data.coin||this._data.jackpot)) {
            if(this._data.coin) {
                this.jackpot.active = false;
                this.label.node.active = true;
                this.label.node.scaleX = 1;
                this.label.string = Global.convertNumToShort(this._data.coin);
            }else {
                this.jackpot.active = true;
                this.label.node.active = false;
                this.jackpot.getComponent("ImgSwitchCmp").setIndex(this._data.jackpot-1);
            }
        }else {
            this.label.node.active = false;
            this.jackpot.active = false;
        }
    },

    /**
     * 移动到最低点
     * @override
     * @constructor
     */
    StopMoveDeep() {
        if(!SlotsFacade.dm.getSpinData()) {
            return;
        }
        if(SlotsFacade.dm.getGameCfg().isWildKind(this._id)) {
            SlotsFacade.soundMgr.playEffect("sound_WildGorilla_wild_ground");
            this.playStopAnimation();
        }
    },

    /**
     * @override
     */
    StopMoveEnd() {
        // 播放idle动画
        let NeedIdleIds = SlotsFacade.dm.getGameCfg().NeedIdleIds;
        if(NeedIdleIds.includes(this._id)) {
            let rewardIdxs = SlotsFacade.dm.getSpinData().rewardIdxs;
            if(!rewardIdxs.includes(this._data.idx)) {
                this.playidleAnimation();
            }
        }
        if(this._data && this._data.isWinBonus) {
            this.showBonusKuang(true);
        }
    },

    /**
     * @override
     */
    playStopAnimation(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    let stopAni = cfg.symbol[id].stop_ani;
                    let idleAni = cfg.symbol[id].idle_ani;
                    nodeSp.setAnimation(0, stopAni.name,false);
                    if(idleAni) {
                        nodeSp.addAnimation(0, idleAni.name, true);
                    }
                }
            }
        }
    },

    /**
     * @override
     * @returns {boolean}
     */
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton);
                if(nodeSp){
                    let triggerAni = cfg.symbol[id].trigger_ani.name;
                    nodeSp.setAnimation(0, triggerAni, cfg.symbol[id].trigger_ani.loop);
                }
            }
            let label = aniNode.getChildByName("label");
            if(!label.active && this._data.coin) {
                label.active = true;
                label.getComponent(cc.Label).string = Global.convertNumToShort(this._data.coin);
            }
        }
        return isPlay;
    },

    /**
     * scatter 图标不显示中奖框
     * @override
     */
    ShowKuang(boo) {
        if(this._id == SlotsFacade.dm.getGameCfg().scatterId) {
            boo = false;
        }
        this._super(boo);
    },

    /**
     * 显示bonus 中奖框
     * @param boo
     */
    showBonusKuang(boo) {
        boo = boo || false;
        this.bonusKuang.active = boo;
    },

    /**
     * 播放bonus中奖
     */
    playBonusAni() {
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(id != cfg.bonusId) {
            return;
        }
        if(this._showNode){
            this._showNode.active = false
        }
        let itemCfg = cfg.symbol[id];
        let aniNode = this.setAnimationToTop(true);
        aniNode.active = true;
        let topShowNode = cc.find(itemCfg.win_node,aniNode);
        topShowNode.active = true;
        aniNode.zIndex = itemCfg.bonus_ani.zIndex - this._symbolIdx + this._reelIdx*10;
        let nodeSp = topShowNode.getComponent(sp.Skeleton);
        let bonusAni = itemCfg.bonus_ani.name;
        nodeSp.setAnimation(0, bonusAni, false);

        this.showBonusKuang(false);
    }
});
